ck public/lan-discovery.js && node --check public/announcement-forms.js && node --check public/teams.js && node --check packages/plugin/teams.mjs && node --check packages/plugin/peak-reminders.mjs && node --check relay/broker.cjs && node --check relay/quota.cjs && node --check relay/sponsorship.cjs && node --check relay/basic-policy.cjs && node --check relay/sponsor/portal.js && node --check public/sponsor-entry.js && node --check public/cache-upgrade.js && node --check public/relay-devices.js && node --check public/relay-settings.js && node --check gateway.js && node --check gateway-stats.cjs && node --check packages/plugin/plugin-center.mjs && node --check packages/plugin/insights.mjs && node --check packages/plugin/skills.mjs && node --check public/insights.js && node --check public/extensions.js && node --check public/chat-files.js && node --check packages/plugin/session-file.mjs && node --check public/skills.js && node --check public/plugin.js && node --check public/plugin-center.js && node --check packages/plugin/index.mjs && node --check public/turn-results.js && node --check public/subagents.js && node --check public/workflow.js && node --check public/operations.js && node --check public/network.js && node --check public/link-check.js && node --check public/activity.js && node --check public/history.js && node --check public/app.js && node --check public/admin.js && node --check public/i18n.js && node --check public/theme.js && node --check public/sha256.js && node --check public/genui.js && node --check public/md.js && node --check public/desktop/desktop.js && node --check public/desktop/i18n.js && node --test tests/*.test.js\",\n    \"test-windows-files\": \"node --test tests/windows-files.test.js tests/windows-gateway.test.js\",\n    \"test-stats\": \"node --test tests/stats.test.js\",\n    \"sync-app\": \"npx cap sync android\",\n    \"build-app\": \"node scripts/build-app.mjs\",\n    \"build-bin\": \"pkg . --no-bytecode --public-packages \\\"*\\\" --pub